// src/display/ui/messageMore.js
// NetHack-style "--More--" message queue.
// Queues messages that arrive during a single game tick.  When multiple
// messages are pending the ticker shows one at a time with "--More--"
// and locks player input until the queue is drained.

const LOCK_KEY = "messageMore";

/**
 * @typedef {Object} MessageMoreQueue
 * @property {(entry: any) => void} push       — feed a new message
 * @property {() => void}           advance    — Space / Enter / tap
 * @property {() => void}           beginBatch — call before world.tick
 * @property {() => boolean}        isActive   — true while --More-- is gating
 * @property {() => any[]}          pending    — snapshot of remaining queue
 */

/**
 * @param {Object}   opts
 * @param {(message: any, hasMore: boolean) => void} opts.onDisplay
 *        Called each time the visible topline message changes.
 * @param {() => void} opts.onClear
 *        Called when the queue is drained and normal ticker can resume.
 * @returns {MessageMoreQueue}
 */
export function createMessageMoreQueue({ onDisplay, onClear }) {
  /** @type {any[]} */
  const queue = [];
  /** @type {any|null} */
  let current = null;
  let gating = false;        // true while --More-- prompt is up and input is locked
  let batchScheduled = false; // true while a microtask processBatch is pending
  let armed = false;          // false until first beginBatch — avoids deadlock on startup messages

  // --More-- is display-only — never locks input.
  function lock() {}
  function unlock() {}

  /**
   * Feed a new message into the queue.
   * All messages from a single world.tick arrive synchronously, so we
   * accumulate them and process the batch in a microtask (before repaint).
   */
  function push(entry) {
    if (!armed) return; // Ignore startup messages — no player action yet.
    queue.push(entry);
    if (!batchScheduled) {
      batchScheduled = true;
      queueMicrotask(processBatch);
    }
  }

  /** Microtask: decide whether the batch needs --More-- gating. */
  function processBatch() {
    batchScheduled = false;
    if (queue.length <= 1) {
      // Single (or zero) message — no gating needed.  Normal ticker handles it.
      queue.length = 0;
      current = null;
      onClear();
      return;
    }
    // Multiple messages — show first with "--More--" and lock input.
    current = queue.shift();
    lock();
    onDisplay(current, queue.length > 0);
  }

  /** Advance to next queued message (Space / Enter / tap). */
  function advance() {
    if (!gating) return;
    if (queue.length > 0) {
      current = queue.shift();
      const hasMore = queue.length > 0;
      onDisplay(current, hasMore);
      if (!hasMore) {
        // Last message — unlock input but keep message visible until next action.
        unlock();
      }
    } else {
      // Safety: queue empty, clear everything.
      current = null;
      unlock();
      onClear();
    }
  }

  /**
   * Signal that a new player action is about to process.
   * Flushes any leftover queue so stale messages don't block the next turn.
   */
  function beginBatch() {
    armed = true;
    current = null;
    queue.length = 0;
    batchScheduled = false;
    unlock();
    onClear();
  }

  function isActive() {
    return gating;
  }

  function pending() {
    return queue.slice();
  }

  return Object.freeze({ push, advance, beginBatch, isActive, pending });
}

  /**
   * Dynamically update the input mode and walk interval (called when settings change).
   * @param {'walk'|'gesture'|'joystick'} mode
   * @param {number} [walkInterval]
   */
  setMode(mode, walkInterval) {
    if (mode === 'walk' || mode === 'gesture' || mode === 'joystick') this._mode = mode;
    if (Number.isFinite(walkInterval) && walkInterval > 0) this._walkInterval = walkInterval;
    this._cancelWalkRepeat();
    this._emitUi("ui:joystickProgress", { active: false });
  }

  onAction(handler) {
    this.handlers.add(handler);
    return () => this.handlers.delete(handler);
  }

  registerHotspot(id, element, action) {
    if (!element) return () => { };
    const rec = { element, action };
    this.hotspots.set(id, rec);
    const click = (ev) => {
      ev.preventDefault();
      this._emit(action);
    };
    element.addEventListener("click", click, { passive: false });
    return () => {
      element.removeEventListener("click", click);
      this.hotspots.delete(id);
    };
  }

  _emit(action) {
    for (const h of this.handlers) try { h(action); } catch (e) { console.debug('[InputManager] handler failed:', e); }
  }

  _bind() {
    this.target.addEventListener("keydown", this._onKeyDown);
    this.target.addEventListener("ui:beginAttackDirection", this._onAttackDirectionRequest);
    this.target.addEventListener("ui:inputSettingsChanged", this._onSettingsChanged);
    const el = this._canvas || this.target;
    el.addEventListener("pointerdown", this._onPointerDown, { passive: false });
    el.addEventListener("pointermove", this._onPointerMove, { passive: false });
    el.addEventListener("pointerup", this._onPointerUp, { passive: false });
    el.addEventListener("pointercancel", this._onPointerCancel, { passive: false });
  }

  _unbind() {
    this.target.removeEventListener("keydown", this._onKeyDown);
    this.target.removeEventListener("ui:beginAttackDirection", this._onAttackDirectionRequest);
    this.target.removeEventListener("ui:inputSettingsChanged", this._onSettingsChanged);
    const el = this._canvas || this.target;
    el.removeEventListener("pointerdown", this._onPointerDown);
    el.removeEventListener("pointermove", this._onPointerMove);
    el.removeEventListener("pointerup", this._onPointerUp);
    el.removeEventListener("pointercancel", this._onPointerCancel);
  }

  _handleKeyDown(e) {
    const { key, code } = e;
    const lowerKey = key?.toLowerCase?.();

    // Never intercept game keys when the user is typing in a text field (e.g. name input)
