class FakeElement extends EventTarget {
  constructor() {
    super();
    this.style = {};
    this.children = [];
    this.textContent = "";
    this.innerHTML = "";
    this.offsetWidth = 280;
    this.offsetHeight = 120;
  }

  appendChild(child) { this.children.push(child); }
